RUN_TRAINING=false
if RUN_TRAINING
    include(joinpath(ROOT,"experiments","train_english_basics.jl"))
    train_english(;budget_seconds=40*60)
    initial=load_checkpoint(joinpath(OUT,"initial.jls"))
end
trained=load_checkpoint(joinpath(OUT,"best.jls"))
model=trained.model
@assert trained.vocab==tok.tokens
@assert all(p isa Array for p in Flux.trainables(model))
@assert trained.metadata["tokenizer_sha256"]==bytes2hex(sha256(read(joinpath(DATA,"tokenizer.json"))))
@assert trained.metadata["train_sha256"]==bytes2hex(sha256(read(joinpath(DATA,"train.bin"))))
@printf("Measured process duration: %.2f minutes | best step %d | last step %d\n",
    trained.metadata["elapsed_seconds"]/60,trained.metadata["best_step"],trained.metadata["last_step"])
println("Training GPU: ",trained.metadata["gpu"])
println("Stop reason: ",trained.metadata["stop_reason"])
